Vinm vim 0 dc 0.5 ac -0.5 pulse(0.55 0.45 10n 0.1n 0.1n 10n 20n)

.control
* 1. Operating Point Analysis
op
let idd = -i(vdd)
let power = idd * 1.8
let vout_cm = (v(vop) + v(vom)) / 2.0
let vin_cm = (v(vp) + v(vm)) / 2.0
print idd power vout_cm vin_cm

* 2. AC Analysis for Gain and Bandwidth
ac dec 50 1k 10G
let vout_diff = v(vop) - v(vom)
let vin_diff = v(vip) - v(vim)
let gain_mag = mag(vout_diff) / mag(vin_diff)
let gain_db = 20 * log10(gain_mag)
let phase_deg = 180 / PI * (cph(vout_diff) - cph(vin_diff))
meas ac open_loop_gain max gain_db
meas ac unity_gain_frequency when gain_db=0 fall=1

* 3. Transient Analysis for Step Response & Settling Time
tran 0.05n 90n
let vodiff = v(vop) - v(vom)
meas tran v_init find vodiff at=9.9n
meas tran v_final find vodiff at=19.0n
meas tran t_settle trig vodiff val=-0.1 rise=1 targ vodiff val=0.198 rise=1

quit
.endc
.end

